"""Mutation catalogue. file is relative to portfolio_engine/. Each mutant = list of (old,new) exact single-occurrence replacements applied to a COPY (scratch mirror)."""
PY='python/pe/'; CP='cpp/include/pe/'
LED=PY+'ledger.py'; LIN=PY+'lineage.py'; REP=PY+'replay.py'; HIS=PY+'generators/historical.py'
M=[
dict(id='M01',name='duplicate opening allocation',file=LIN,edits=[("    def opening_allocation(self, f, episode_id, qty):\n","    def opening_allocation(self, f, episode_id, qty):\n        self.observed.append(('OA', f'OA:{f.fill_id}', f.fill_id, f.parent_order_id, f.instrument_id, episode_id, f.timestamp_s, f.side, qty, f.price_paise, f.module_tag, f.source_row_id, f.execution_mode))\n")],expected='I-unique-observed-ids / OA count 23,684'),
dict(id='M02',name='dropped closing portion on every reversal fill',file=LIN,edits=[("    def closing_portion(self, f, episode_id, qty):\n","    def closing_portion(self, f, episode_id, qty):\n        if qty < f.quantity: return\n")],expected='I5 OA+CP=qty; CP count; reversal I11'),
dict(id='M03',name='dropped closing portion sparse (1 in 997 source rows)',file=LIN,edits=[("    def closing_portion(self, f, episode_id, qty):\n","    def closing_portion(self, f, episode_id, qty):\n        if f.source_row_id > 0 and f.source_row_id % 997 == 0: return\n")],expected='I4/I5; CP membership vs raw reference'),
dict(id='M04',name='sign flip of FIFO/LIFO realized P&L',file=LED,edits=[("p_ = d * (px - lot[1]) * take","p_ = -d * (px - lot[1]) * take")],expected='realized P&L vs TP-01 / reference'),
dict(id='M05',name='AVG realized P&L sign flip',file=LED,edits=[("pnl = d * (px - st.pool_px) * close_q","pnl = -d * (px - st.pool_px) * close_q")],expected='AVG realized vs TP-01 / reference'),
dict(id='M06',name='price off by one tick on 1 in 1000 historical fills',file=HIS,edits=[("int(r.sgn), int(r.qty_units), px,","int(r.sgn), int(r.qty_units), px + (5 if int(r.src_row) % 1000 == 0 else 0),")],expected='fill price vs raw col 137; realized P&L'),
dict(id='M07',name='wrong price column (order running average col 18 instead of per-fill col 137)',file=HIS,edits=[("r.px_fill","r.px_order_avg")],expected='fill price vs raw col 137'),
dict(id='M08',name='buy/sell reversed on 1 in 4001 historical fills',file=HIS,edits=[("int(r.epoch), int(r.sgn),","int(r.epoch), (-int(r.sgn) if int(r.src_row) % 4001 == 0 else int(r.sgn)),")],expected='fill side vs raw col 11; roles; realized P&L'),
dict(id='M09',name='wrong parent id on closing portions (stale parent of previous CP)',file=LIN,edits=[("    def closing_portion(self, f, episode_id, qty):\n        self.observed.append(('CP', f'CP:{f.fill_id}', f.fill_id, f.parent_order_id,","    def closing_portion(self, f, episode_id, qty):\n        _p = getattr(self, '_lastp', f.parent_order_id); self._lastp = f.parent_order_id\n        self.observed.append(('CP', f'CP:{f.fill_id}', f.fill_id, _p,")],expected='I5 row-vs-fill; parent roles'),
dict(id='M10',name='same-second order swap (reverse source-row tie-break)',file=REP,edits=[("key=lambda f: (f.timestamp_s, tk(f.side), f.source_row_id, f.fill_id))","key=lambda f: (f.timestamp_s, tk(f.side), -f.source_row_id, f.fill_id))")],expected='episode/role identity vs TP-01 and raw reference'),
dict(id='M11',name='19800-second timestamp shift in historical generator',file=HIS,edits=[("int(r.epoch), int(r.sgn),","int(r.epoch) + 19800, int(r.sgn),")],expected='timestamp vs raw col 161'),
dict(id='M12',name='reversal opening allocation assigned to the OLD (closed) episode',file=LED,edits=[("self.lin.opening_allocation(f, eid_open, open_q);","self.lin.opening_allocation(f, eid_close if reversal else eid_open, open_q);")],expected='I11; OA episode vs reference'),
dict(id='M13',name='FIFO consumes the LAST lot (wrong closing source)',file=LED,edits=[("lot = st.lots[0] if m == 'FIFO' else st.lots[-1]","lot = st.lots[-1]"),("st.lots.popleft() if m == 'FIFO' else st.lots.pop()","st.lots.pop()")],expected='FIFO P&L vs TP-01; CA pairs vs reference'),
dict(id='M14',name='remaining slice quantity off by one lot (65)',file=LIN,edits=[("rows.append((lot[2], st.eid, lot[0], lot[1]))","rows.append((lot[2], st.eid, lot[0] + 65, lot[1]))")],expected='I3/I7'),
dict(id='M15',name='remaining expired-unclosed units off by one lot in dump',file=REP,edits=[("stat[iid] = 'EXPIRED_UNCLOSED'; exp_units += inv","stat[iid] = 'EXPIRED_UNCLOSED'; exp_units += inv + 65")],expected='TOTAL remaining_expired_unclosed_units vs 37,480'),
dict(id='M16',name='convention leak: AVG observed OA price differs',file=LIN,edits=[("('OA', f'OA:{f.fill_id}', f.fill_id, f.parent_order_id, f.instrument_id, episode_id, f.timestamp_s, f.side, qty, f.price_paise,","('OA', f'OA:{f.fill_id}', f.fill_id, f.parent_order_id, f.instrument_id, episode_id, f.timestamp_s, f.side, qty, f.price_paise + (5 if self.method == 'AVG' else 0),")],expected='separation guard in LineageSet; observed layer vs reference'),
dict(id='M17',name='LIFO pops the wrong (front) lot when exhausted',file=LED,edits=[("st.lots.popleft() if m == 'FIFO' else st.lots.pop()","st.lots.popleft()")],expected='lots-reconcile invariant; LIFO CA vs reference'),
dict(id='M18',name='reversal opens full fill quantity (close+open != q)',file=LED,edits=[("open_q = q - close_q\n            if open_q > 0: reversal = True","open_q = (q if q > close_q else 0)\n            if open_q > 0: reversal = True")],expected='role arithmetic guard'),
dict(id='M19',name='expiry boundary < instead of <= in episode terminal status',file=LIN,edits=[("else 'OPEN_AT_END_OF_DATA'\n\n\ndef episodes_tsv","else 'OPEN_AT_END_OF_DATA'\n\n\ndef episodes_tsv"),("return 'EXPIRED_UNCLOSED' if iso_day(instruments[ep['instrument_id']].expiry) <= last_day","return 'EXPIRED_UNCLOSED' if iso_day(instruments[ep['instrument_id']].expiry) < last_day")],expected='terminal_status counts (81 EXPIRED_UNCLOSED)'),
dict(id='M20',name='flagged duplicate fills no longer ignored',file=REP,edits=[("live = [f for f in ordered if not f.is_duplicate_fill]","live = list(ordered)")],expected='duplicate synthetic fixtures (real data has none)'),
dict(id='M21',name='direction of reversal-created episodes recorded wrong',file=LED,edits=[("direction=direction, opened=0","direction=(-direction if reversal else direction), opened=0")],expected='episode direction vs TP-01 / reference'),
dict(id='M22',name='tie-order keys sells_first/buys_first swapped (Python only)',file=REP,edits=[("'sells_first': lambda s: 0 if s < 0 else 1, 'buys_first': lambda s: 0 if s > 0 else 1","'sells_first': lambda s: 0 if s > 0 else 1, 'buys_first': lambda s: 0 if s < 0 else 1")],expected='cross-language parity; tie-order tests'),
dict(id='M23',name='cash flow sign flipped',file=LED,edits=[("self.cash += -sg * q * px","self.cash += sg * q * px")],expected='cash identity invariant'),
dict(id='C01',name='C++ FIFO consumes last lot',file=CP+'ledger.hpp',edits=[("Lot& lot = (method == Method::FIFO) ? st.lots.front() : st.lots.back();","Lot& lot = st.lots.back();"),("if (method == Method::FIFO) st.lots.pop_front(); else st.lots.pop_back();","st.lots.pop_back();")],expected='parity tests; fuzz'),
dict(id='C02',name='C++ tie keys swapped',file=CP+'replay.hpp',edits=[('if (tie == "sells_first") return side < 0 ? 0 : 1; if (tie == "buys_first") return side > 0 ? 0 : 1;','if (tie == "sells_first") return side > 0 ? 0 : 1; if (tie == "buys_first") return side < 0 ? 0 : 1;')],expected='parity tests; fuzz'),
dict(id='C03',name='C++ AVG pool average floored',file=CP+'ledger.hpp',edits=[("st.pool_px = (st.pool_px * (double)st.pool_q + (double)(px * open_q)) / (double)(st.pool_q + open_q);","st.pool_px = std::floor((st.pool_px * (double)st.pool_q + (double)(px * open_q)) / (double)(st.pool_q + open_q));")],expected='parity tests; fuzz'),
]
